;	Moderner Busy-Wait-Delay für HCS12;	Preservation: X und Y werden vor Schleifen gesichert;	Aufgeteilt in eine generische Millisekunden-Subroutine und eine feste 0,5s-Verzögerung	INCLUDE 'mc9s12dp256.inc'; Exporte	XDEF delay_ms      ; Variabler Delay in ms	XDEF delay_0_5sec  ; Fester 500ms-Delay; Feintuning: Anzahl der Schleifendurchläufe pro ms; Passe diesen Wert an deine Taktfrequenz/Simulator anCYCLES_PER_MS   EQU 8000.init: SECTION; -----------------------------------------------------------------------------; delay_ms;  Einmal pro Millisekunde wird eine Schleife mit CYCLES_PER_MS Wiederholungen;  ausgeführt. In X übergibt man die gewünschten Millisekunden.;  Er schützt X und Y vor Veränderungen.; -----------------------------------------------------------------------------delay_ms:	PSHX            ; X sichern	PSHY            ; Y sichernms_loop:	LDY  #CYCLES_PER_MS  ; Lade Schleifenzählercycle_loop:	DBNE Y, cycle_loop   ; Y--, solange >0 wiederholen	DBNE X, ms_loop      ; X--, solange >0 ms-Schleife wiederholen	PULY            	PULX            	RTS             ; -----------------------------------------------------------------------------; delay_0_5sec;  Einfacher Aufruf: wartet konstant 500ms mit Hilfe von delay_ms; -----------------------------------------------------------------------------delay_0_5sec:	PSHX            	LDX  #500       ; 500 Millisekunden	JSR  delay_ms   ; Variabler Delay	PULX           	RTS             